pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        LogHelper log = new LogHelper();
        vm.assume(actor != address(0));
        vm.assume(actor != address(log));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint256).max / 2);

        vm.prank(actor);
        c.SetLogFile(address(log));
        c.Initialized();

        vm.deal(actor, amount);
        vm.prank(actor);
        try c.Deposit{value: amount}() {
            assertTrue(log.History(0).Sender == actor && log.History(0).Val == amount);
        } catch {
            assertTrue(false);
        }
    }
}

contract LogHelper {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // keep the log address at an account whose (unchecked) call cannot break the flow
        c.SetLogFile(actor);
        uint256 a = bound(amount, 1, 1 ether);
        uint256 b = bound(uint256(amount) >> 96 | (amount > 0 ? uint256(amount) % 1 ether + 1 : 1), 1, 1 ether);

        vm.deal(actor, a);
        vm.prank(actor);
        c.Deposit{value: a}();
        vm.deal(actor, b);
        vm.prank(actor);
        c.Deposit{value: b}();

        assertEq(c.balances(actor), a + b);
    }
}

