pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = uint96(bound(amount, 1, type(uint96).max));

        LogFile log = c.Log();
        uint256 before = log.History().length;

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        assertTrue(c.balances(actor) == amount && log.History().length == before + 1);
    }
}

