contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        require(amount == 0);
        require(address(this).balance >= amount);
        uint256 balBefore = c.balances(address(this));
        (bool ok,) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.Deposit.selector)
        );
        uint256 balAfter = c.balances(address(this));
        assert(ok && balAfter == balBefore);
    }
}

